-- Robokalam core schema for MySQL 8.0.16+ and MariaDB 10.6+ (Hostinger).
-- Times are UTC (DATETIME(3)); ids are UUID strings generated by the app.
-- Access control lives in application code: every query is scoped to the
-- signed-in account (see src/lib/db.ts). CHECK constraints here enforce the
-- rules that must hold no matter what code runs.

CREATE TABLE IF NOT EXISTS accounts (
  id CHAR(36) PRIMARY KEY,
  phone_e164 VARCHAR(16) NOT NULL UNIQUE,
  role VARCHAR(20) NOT NULL DEFAULT 'parent',
  display_name VARCHAR(80),
  language VARCHAR(2) NOT NULL DEFAULT 'en',
  region VARCHAR(8) NOT NULL DEFAULT 'ts-ap',
  adult_declared_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  erased_at DATETIME(3),
  CONSTRAINT accounts_phone CHECK (phone_e164 REGEXP '^[+][1-9][0-9]{7,14}$'),
  CONSTRAINT accounts_role CHECK (role IN ('parent','adult_learner','fellow','trainer','school_admin','ops','safeguarding','csr')),
  CONSTRAINT accounts_lang CHECK (language IN ('en','te','hi')),
  CONSTRAINT accounts_region CHECK (region IN ('ts-ap','india','intl'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS otp_challenges (
  id CHAR(36) PRIMARY KEY,
  phone_e164 VARCHAR(16) NOT NULL,
  code_hash CHAR(64) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  attempts INT NOT NULL DEFAULT 0,
  consumed_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX otp_phone_idx (phone_e164, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sessions (
  id CHAR(36) PRIMARY KEY,
  token_hash CHAR(64) NOT NULL UNIQUE,
  account_id CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at DATETIME(3) NOT NULL,
  revoked_at DATETIME(3),
  CONSTRAINT sessions_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Only first name and age band: never date of birth, school or address.
CREATE TABLE IF NOT EXISTS learners (
  id CHAR(36) PRIMARY KEY,
  guardian_account_id CHAR(36) NOT NULL,
  first_name VARCHAR(40) NOT NULL,
  age_band VARCHAR(5) NOT NULL,
  interests JSON NOT NULL,
  portfolio_public BOOLEAN NOT NULL DEFAULT FALSE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  erased_at DATETIME(3),
  INDEX learners_guardian_idx (guardian_account_id),
  CONSTRAINT learners_guardian FOREIGN KEY (guardian_account_id) REFERENCES accounts(id),
  CONSTRAINT learners_name CHECK (CHAR_LENGTH(first_name) BETWEEN 1 AND 40),
  CONSTRAINT learners_band CHECK (age_band IN ('6-8','9-11','12-14','15-17','18+'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS consent_notices (
  id VARCHAR(64) PRIMARY KEY,
  language VARCHAR(2) NOT NULL,
  title VARCHAR(200) NOT NULL,
  body JSON NOT NULL,
  sha256 CHAR(64) NOT NULL,
  approved BOOLEAN NOT NULL DEFAULT FALSE,
  published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Append-only. Current state = latest event per (learner, purpose).
CREATE TABLE IF NOT EXISTS consent_events (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  learner_id CHAR(36) NOT NULL,
  guardian_account_id CHAR(36) NOT NULL,
  purpose VARCHAR(24) NOT NULL,
  granted BOOLEAN NOT NULL,
  notice_id VARCHAR(64) NOT NULL,
  method VARCHAR(80) NOT NULL,
  evidence JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX consent_lookup_idx (learner_id, purpose, id),
  CONSTRAINT consent_learner FOREIGN KEY (learner_id) REFERENCES learners(id),
  CONSTRAINT consent_guardian FOREIGN KEY (guardian_account_id) REFERENCES accounts(id),
  CONSTRAINT consent_notice FOREIGN KEY (notice_id) REFERENCES consent_notices(id),
  CONSTRAINT consent_purpose CHECK (purpose IN ('account','live_classes','class_recording','ai_helper','portfolio_sharing','whatsapp','follow_up'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS courses (
  id CHAR(36) PRIMARY KEY,
  slug VARCHAR(80) NOT NULL UNIQUE,
  title VARCHAR(160) NOT NULL,
  world VARCHAR(12) NOT NULL,
  programme VARCHAR(80),
  age_min INT NOT NULL,
  age_max INT,
  outcome VARCHAR(400) NOT NULL,
  batch_size_max INT NOT NULL,
  sessions INT NOT NULL DEFAULT 1,
  kit VARCHAR(160),
  fee_paise INT,
  fee_approved BOOLEAN NOT NULL DEFAULT FALSE,
  sample BOOLEAN NOT NULL DEFAULT FALSE,
  published BOOLEAN NOT NULL DEFAULT FALSE,
  kind VARCHAR(16) NOT NULL DEFAULT 'course',
  CONSTRAINT courses_world CHECK (world IN ('robotics','iot','ai','finlit','space','coding')),
  CONSTRAINT courses_batch CHECK (batch_size_max BETWEEN 2 AND 30),
  CONSTRAINT courses_fee CHECK (fee_paise IS NULL OR fee_paise >= 0),
  CONSTRAINT courses_kind CHECK (kind IN ('course','build_session'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS batches (
  id CHAR(36) PRIMARY KEY,
  course_id CHAR(36) NOT NULL,
  starts_at DATETIME(3) NOT NULL,
  duration_min INT NOT NULL,
  capacity INT NOT NULL,
  language VARCHAR(2) NOT NULL DEFAULT 'en',
  mode VARCHAR(8) NOT NULL,
  location VARCHAR(200),
  educator_label VARCHAR(80),
  educator_fellow_id CHAR(36),
  INDEX batches_course_idx (course_id, starts_at),
  CONSTRAINT batches_course FOREIGN KEY (course_id) REFERENCES courses(id),
  CONSTRAINT batches_capacity CHECK (capacity BETWEEN 1 AND 30),
  CONSTRAINT batches_mode CHECK (mode IN ('online','offline'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bookings (
  id CHAR(36) PRIMARY KEY,
  batch_id CHAR(36) NOT NULL,
  learner_id CHAR(36) NOT NULL,
  guardian_account_id CHAR(36) NOT NULL,
  status VARCHAR(16) NOT NULL,
  feedback TEXT,
  next_step VARCHAR(300),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY bookings_once (batch_id, learner_id),
  INDEX bookings_guardian_idx (guardian_account_id),
  CONSTRAINT bookings_batch FOREIGN KEY (batch_id) REFERENCES batches(id),
  CONSTRAINT bookings_learner FOREIGN KEY (learner_id) REFERENCES learners(id),
  CONSTRAINT bookings_guardian FOREIGN KEY (guardian_account_id) REFERENCES accounts(id),
  CONSTRAINT bookings_status CHECK (status IN ('pending_payment','confirmed','attended','no_show','cancelled','refunded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS counters (
  name VARCHAR(32) PRIMARY KEY,
  value BIGINT NOT NULL
) ENGINE=InnoDB;
INSERT IGNORE INTO counters (name, value) VALUES ('invoice', 0);

CREATE TABLE IF NOT EXISTS orders (
  id CHAR(36) PRIMARY KEY,
  booking_id CHAR(36) NOT NULL,
  account_id CHAR(36) NOT NULL,
  amount_paise INT NOT NULL,
  gst_paise INT NOT NULL,
  currency CHAR(3) NOT NULL DEFAULT 'INR',
  status VARCHAR(20) NOT NULL,
  provider VARCHAR(16) NOT NULL,
  provider_order_id VARCHAR(64) UNIQUE,
  provider_payment_id VARCHAR(64) UNIQUE,
  invoice_no VARCHAR(32) UNIQUE,
  paid_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX orders_account_idx (account_id),
  CONSTRAINT orders_booking FOREIGN KEY (booking_id) REFERENCES bookings(id),
  CONSTRAINT orders_account FOREIGN KEY (account_id) REFERENCES accounts(id),
  CONSTRAINT orders_amount CHECK (amount_paise > 0 AND gst_paise >= 0),
  CONSTRAINT orders_status CHECK (status IN ('created','paid','failed','refunded','partially_refunded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Double-entry ledger. The app writes a journal and all its postings in one
-- transaction and refuses any journal that does not sum to zero.
CREATE TABLE IF NOT EXISTS ledger_journals (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  kind VARCHAR(32) NOT NULL,
  ref VARCHAR(100) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY ledger_once (kind, ref)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ledger_postings (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  journal_id BIGINT NOT NULL,
  account VARCHAR(24) NOT NULL,
  amount_paise BIGINT NOT NULL,
  CONSTRAINT postings_journal FOREIGN KEY (journal_id) REFERENCES ledger_journals(id),
  CONSTRAINT postings_account CHECK (account IN ('gateway_clearing','learner_escrow','gst_payable','platform_revenue','educator_payable','refunds','platform_expense','deductions_payable','payouts_bank')),
  CONSTRAINT postings_nonzero CHECK (amount_paise <> 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS refund_requests (
  id CHAR(36) PRIMARY KEY,
  order_id CHAR(36) NOT NULL,
  account_id CHAR(36) NOT NULL,
  reason VARCHAR(500) NOT NULL,
  amount_paise INT NOT NULL,
  decision JSON NOT NULL,
  status VARCHAR(12) NOT NULL,
  provider_refund_id VARCHAR(64),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  decided_at DATETIME(3),
  -- One open request per order: open_order_id must equal order_id exactly while the
  -- request is open and be NULL otherwise (CHECKs below), and it is UNIQUE.
  open_order_id CHAR(36),
  UNIQUE KEY one_open_refund (open_order_id),
  CONSTRAINT refunds_open_set CHECK (status NOT IN ('requested','approved') OR open_order_id = order_id),
  CONSTRAINT refunds_open_clear CHECK (status IN ('requested','approved') OR open_order_id IS NULL),
  CONSTRAINT refunds_order FOREIGN KEY (order_id) REFERENCES orders(id),
  CONSTRAINT refunds_account FOREIGN KEY (account_id) REFERENCES accounts(id),
  CONSTRAINT refunds_reason CHECK (CHAR_LENGTH(reason) BETWEEN 3 AND 500),
  CONSTRAINT refunds_amount CHECK (amount_paise > 0),
  CONSTRAINT refunds_status CHECK (status IN ('requested','approved','rejected','paid'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS projects (
  id VARCHAR(40) PRIMARY KEY,
  world VARCHAR(12) NOT NULL,
  level INT NOT NULL,
  title VARCHAR(80) NOT NULL,
  builds VARCHAR(200) NOT NULL,
  prerequisites JSON NOT NULL,
  age_min INT NOT NULL DEFAULT 6
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS learner_progress (
  learner_id CHAR(36) NOT NULL,
  project_id VARCHAR(40) NOT NULL,
  status VARCHAR(8) NOT NULL,
  reviewed_by VARCHAR(64),
  completed_at DATETIME(3),
  PRIMARY KEY (learner_id, project_id),
  CONSTRAINT progress_learner FOREIGN KEY (learner_id) REFERENCES learners(id),
  CONSTRAINT progress_project FOREIGN KEY (project_id) REFERENCES projects(id),
  CONSTRAINT progress_status CHECK (status IN ('started','built'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS safety_reports (
  id CHAR(36) PRIMARY KEY,
  reporter_account_id CHAR(36),
  learner_id CHAR(36),
  page VARCHAR(200) NOT NULL,
  category VARCHAR(20) NOT NULL,
  details TEXT NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'open',
  respond_by DATETIME(3) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT reports_category CHECK (category IN ('safety','contact_details','inappropriate','bullying','technical','other')),
  CONSTRAINT reports_status CHECK (status IN ('open','acknowledged','actioned','closed')),
  CONSTRAINT reports_details CHECK (CHAR_LENGTH(details) BETWEEN 1 AND 2000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS data_requests (
  id CHAR(36) PRIMARY KEY,
  account_id CHAR(36) NOT NULL,
  learner_id CHAR(36),
  kind VARCHAR(8) NOT NULL,
  status VARCHAR(8) NOT NULL DEFAULT 'received',
  note TEXT,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  completed_at DATETIME(3),
  CONSTRAINT datareq_kind CHECK (kind IN ('export','erase')),
  CONSTRAINT datareq_status CHECK (status IN ('received','done','held'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_log (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  actor_account_id CHAR(36),
  action VARCHAR(40) NOT NULL,
  entity VARCHAR(24) NOT NULL,
  entity_id VARCHAR(64),
  meta JSON,
  at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
